head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#eeece3" value="#eeece3"/><Variable name="page.text" description="Text color" type="color" default="#171717" value="#171717"/><Variable name="theme.accent" description="Accent color" type="color" default="#dce629" value="#dce629"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:'Anton', Impact, sans-serif;--body:Arial, sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
a{color:inherit}a:focus-visible,summary:focus-visible{outline:3px solid currentColor;outline-offset:5px}img{max-width:100%;height:auto}svg{display:block;width:100%;height:auto} .post-title a{text-decoration:none}.post-meta{font-size:.75rem;text-transform:uppercase;letter-spacing:.12em}.post-excerpt{line-height:1.7}.post-media{overflow:hidden}.post-card{min-width:0}.post-card a:hover{text-decoration:underline}.post-card:hover .post-media{filter:saturate(1.15)}.post-media img{transition:transform .4s}.post-card:hover .post-media img{transform:scale(1.035)}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}body{margin:0;background:#eeece3;color:#171717;font-family:Arial,sans-serif}.curb-nav{display:flex;justify-content:space-between;align-items:center;padding:24px 4%;border-bottom:3px solid}.curb-nav .brand{font-size:22px;font-weight:900;letter-spacing:-1px;text-decoration:none}.curb-nav nav{display:flex;gap:25px;font-size:10px;font-weight:900;text-transform:uppercase}.curb-nav nav a{text-decoration:none}.curb-opening{padding:25px 4% 45px}.curb-issue{display:flex;justify-content:space-between;font:9px "Courier New",monospace;letter-spacing:.08em}.curb-opening h1{font-family:Impact,sans-serif;font-size:clamp(66px,11.7vw,165px);font-weight:900;line-height:.86;letter-spacing:-.025em;margin:38px 0 36px}.curb-opening h1 span{color:#eeece3;-webkit-text-stroke:2px #171717}.curb-opener{display:grid;grid-template-columns:1.8fr 1fr;gap:45px;align-items:center}.curb-visual{transform:rotate(-2deg);border:3px solid}.curb-opener aside{padding:15px 0}.curb-stamp{display:inline-block;border:4px solid;padding:12px 20px;transform:rotate(8deg);font:30px/.9 Impact,sans-serif;background:#dce629}.curb-opener p{font-size:27px;line-height:1.07;letter-spacing:-1px;font-weight:bold;margin:28px 0}.curb-opener aside a{font-size:11px;font-weight:900;text-underline-offset:5px}.curb-field{display:grid;grid-template-columns:1fr 2fr;gap:40px;background:#171717;color:#eeece3;padding:45px 4%}.curb-field h2{font:62px/.95 Impact,sans-serif;color:#dce629;margin:10px 0}.curb-field>div{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.curb-field a{border-top:1px solid #74746b;padding-top:18px;text-decoration:none;transition:color .2s}.curb-field a:hover{color:#dce629}.curb-field b{font:9px "Courier New",monospace;color:#dce629}.curb-field p{font-size:18px;font-weight:bold;line-height:1.18}.curb-field a span{font-size:8px;font-weight:bold;display:block;margin-top:25px}.section-heading{font:52px Impact,sans-serif;letter-spacing:-1px;padding:48px 4% 22px;margin:0;border-bottom:3px solid}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);padding:0 4% 45px;gap:0}.post-card{padding:27px 25px;border-right:2px solid}.post-card:first-child{padding-left:0}.post-card:last-child{border-right:0;padding-right:0}.post-media{aspect-ratio:1.35;background:#dce629;border:2px solid;filter:grayscale(1);margin-bottom:18px}.post-card:hover .post-media{filter:grayscale(0)}.post-meta{font:9px "Courier New",monospace}.post-title{font-size:27px;line-height:.98;font-weight:900;letter-spacing:-1px;text-transform:uppercase}.post-excerpt{font-size:12px}.curb-manifesto{padding:45px 4%;display:flex;gap:45px;align-items:center;background:#dce629;border-top:3px solid;border-bottom:3px solid}.curb-manifesto>span{font-size:150px;line-height:1;transition:transform .6s}.curb-manifesto:hover>span{transform:rotate(90deg)}.curb-manifesto small{font-size:9px;font-weight:bold;letter-spacing:.09em}.curb-manifesto h2{font:clamp(38px,5.2vw,72px)/.95 Impact,sans-serif;margin:20px 0}.curb-manifesto p{font-size:12px;line-height:1.6}.curb-footer{display:flex;justify-content:space-between;align-items:center;padding:30px 4%}.curb-footer strong{font:60px Impact,sans-serif}.curb-footer span{font:9px/1.8 "Courier New",monospace}.curb-footer a{font-size:10px;font-weight:bold}@media(max-width:700px){.curb-nav .brand{font-size:18px}.curb-nav nav{font-size:8px;gap:10px}.curb-issue{font-size:7px}.curb-opening h1{font-size:13vw}.curb-opener{grid-template-columns:1fr}.curb-opener aside{display:flex;align-items:center;gap:20px;flex-wrap:wrap}.curb-opener p{font-size:22px}.curb-field{grid-template-columns:1fr}.curb-field>div{grid-template-columns:1fr}.curb-field h2 br{display:none}.curb-field a p br{display:none}.posts-grid{grid-template-columns:1fr}.post-card,.post-card:first-child,.post-card:last-child{border-right:0;border-bottom:2px solid;padding:25px 0}.curb-manifesto{gap:20px}.curb-manifesto>span{font-size:70px}.curb-footer span{font-size:8px;max-width:175px}} .latest{max-width:none;margin:0;padding:0}
h1,h2,h3{font-family:'Anton', Impact, sans-serif}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
